// claudecast mod: broadcasts this session live to viewers over a public URL.
//
// The claudecast Rust binary runs a local HTTP server (viewer page + feed) and
// the Cloudflare tunnel. This mod replaces the old MCP server and settings hooks:
//   /cast, /cast-stop, /cast-viewers  user commands (no Claude turn needed)
//   prompt.submit                    broadcast user messages + surface viewer questions
//   tool.call                        broadcast tool calls and their results
//   turn.complete                    broadcast assistant responses
//
// Module state is shared between the hooks of this session.

const MAX_OUTPUT = 4000

let active = false // this session is broadcasting
let base = 'http://127.0.0.1:3000'
let binary = 'claudecast'
let port = 3000

export function register(on, options = {}) {
  port = options.port ?? 3000
  binary = options.binaryPath ?? 'claudecast'
  base = 'http://127.0.0.1:' + port

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'cast',
      description: 'Start broadcasting this session live and show the public viewer URL',
      immediate: true,
    })
    await $.command.register({
      name: 'cast-stop',
      description: 'Stop the live broadcast and disconnect all viewers',
      immediate: true,
    })
    await $.command.register({
      name: 'cast-viewers',
      description: 'Show how many viewers are watching the live cast',
      immediate: true,
    })
    return next(e)
  })

  on('command.run', { command: 'cast' }, async ($) => {
    let up
    try {
      up = await ensureServer($)
    } catch (err) {
      return { text: 'claudecast: ' + err + '. ' + spawnHelp() }
    }
    if (!up) {
      return { text: 'claudecast: server did not come up on ' + base + '. ' + spawnHelp() }
    }
    let start
    try {
      start = await post($, '/cast/start', {})
    } catch (err) {
      return { text: 'claudecast: failed to start the cast: ' + err }
    }
    const url = start.public_url || ''
    if (!url) {
      return {
        text:
          'claudecast: no tunnel URL. Is cloudflared installed? ' +
          '(brew install cloudflare/cloudflare/cloudflared)',
      }
    }
    active = true
    $.ui.status('claudecast live · ' + url)
    return {
      text:
        '[claudecast active — public URL: ' + url + ']\n' +
        'Share this URL with your audience. User messages, tool calls and your responses are ' +
        'broadcast automatically from now on. Viewer questions are injected into your context ' +
        'at the start of each turn — treat them as part of the conversation when relevant.',
    }
  })

  on('command.run', { command: 'cast-stop' }, async ($) => {
    if (!active) return { text: 'No active cast. Run /cast to start one.' }
    try {
      await post($, '/cast/stop', {})
    } catch (err) {
      return { text: 'claudecast: stop failed: ' + err }
    }
    active = false
    $.ui.status(undefined)
    return { text: 'claudecast stopped. Viewers have been disconnected.' }
  })

  on('command.run', { command: 'cast-viewers' }, async ($) => {
    if (!active) return { text: 'No active cast. Run /cast to start one.' }
    let status
    try {
      status = await get($, '/status')
    } catch (err) {
      return { text: 'claudecast: server unreachable: ' + err }
    }
    const n = status.viewer_count ?? 0
    const url = status.public_url || base
    return { text: n + (n === 1 ? ' viewer' : ' viewers') + ' watching · ' + url }
  })

  // Broadcast the user's message, then surface pending viewer questions as
  // context only Claude reads — the questions leave the queue once surfaced.
  on('prompt.submit', async ($, e, next) => {
    if (!active) return next(e)
    try {
      await post($, '/user-message', { text: e.text })
    } catch {
      // Broadcasting must never block the prompt.
    }
    let questions = []
    try {
      questions = await get($, '/pending-questions')
    } catch {
      // No questions to surface.
    }
    if (Array.isArray(questions) && questions.length > 0) {
      const block =
        'Viewer questions from the audience watching this session live ' +
        '(answer them as part of your reply when relevant):\n' +
        questions.map((q) => '- ' + q).join('\n')
      return next({ ...e, context: [...(e.context ?? []), block] })
    }
    return next(e)
  })

  // Broadcast every tool call after it runs, with the result the model reads.
  on('tool.call', async ($, e, next) => {
    if (!active) return next(e)
    const result = await next(e)
    try {
      const input = {}
      for (const [key, value] of Object.entries(e)) {
        if (key !== 'tool' && key !== 'tool_use_id' && key !== 'consent' && key !== 'agentId') {
          input[key] = value
        }
      }
      const output =
        typeof result?.text === 'string' ? result.text : JSON.stringify(result?.result ?? '')
      await post($, '/tool-event', {
        name: e.tool,
        input,
        output: String(output).slice(0, MAX_OUTPUT),
      })
    } catch {
      // Broadcasting must never disturb the tool result.
    }
    return result
  })

  // Broadcast Claude's final response for the turn (main conversation only —
  // subagent turns carry agentId and stay off the feed).
  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (active && !e.agentId && e.answer) {
      try {
        await post($, '/assistant-message', { text: e.answer })
      } catch {
        // Broadcasting must never disturb the turn.
      }
    }
    return result
  })

  // End the cast when the session goes away, so no viewer hangs on a dead feed.
  on('session.end', async ($, e, next) => {
    if (active) {
      active = false
      try {
        await post($, '/cast/stop', {})
      } catch {
        // Session is ending either way.
      }
    }
    return next(e)
  })
}

// --- HTTP helpers against the local claudecast server ---

async function get($, path) {
  const res = await $.http.fetch(base + path)
  if (!res.ok) throw new Error('GET ' + path + ' -> ' + res.status)
  return JSON.parse(res.text)
}

async function post($, path, body) {
  const res = await $.http.fetch(base + path, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  })
  if (!res.ok) throw new Error('POST ' + path + ' -> ' + res.status + ' ' + res.text)
  return res.text ? JSON.parse(res.text) : {}
}

// Ensure the local claudecast server is up: reuse a running one, spawn it when
// not. Returns true once /status answers.
async function ensureServer($) {
  if (await serverUp($)) return true
  try {
    // The loop is the child's life: consume it in the background so the server
    // stays up for the rest of the session and dies with it.
    const child = $.process.spawn({ argv: [binary, '--port', String(port)] })
    void (async () => {
      try {
        for await (const _piece of child) {
          // discard the server's output
        }
      } catch {
        // The server exited; the /status polling below reports it.
      }
    })()
  } catch (err) {
    throw new Error('cannot spawn the server: ' + err)
  }
  for (let i = 0; i < 50; i++) {
    await $.clock.sleep(100)
    if (await serverUp($)) return true
  }
  return false
}

async function serverUp($) {
  try {
    await $.http.fetch(base + '/status')
    return true
  } catch {
    return false
  }
}

function spawnHelp() {
  return (
    'Build it with cargo build --release in the claudecast repo, then either put ' +
    'target/release/claudecast on your PATH, set binaryPath in the plugin options, ' +
    'or start it yourself with: ' + binary + ' --port ' + port
  )
}

