{
  "name": "claudecast",
  "version": "0.1.0",
  "description": "Broadcast your Claude Code session live. Viewers watch messages, tool calls and responses in real time in a browser and can ask questions that reach your context automatically.",
  "author": {
    "name": "xdm67x"
  },
  "userConfig": {
    "binaryPath": {
      "type": "string",
      "title": "Server binary path",
      "default": "claudecast",
      "description": "Path to the claudecast server binary (cargo build --release in the claudecast repo, then target/release/claudecast)"
    },
    "port": {
      "type": "number",
      "title": "Server port",
      "default": 3000,
      "description": "Local port the claudecast server listens on"
    }
  }
}
